-- DEN-127.2: escrituras delegadas explícitas; sin delete, equipo, MCP ni configuración.
create or replace function cashflow.denarius_can_operate(p_tenant uuid)returns boolean language sql stable security definer set search_path=cashflow,public,pg_temp as $$select cashflow.denarius_has_permission(p_tenant,'financial.write')or cashflow.denarius_has_permission(p_tenant,'operations.write')$$;
create or replace function cashflow.denarius_create_transaction(p_account_id uuid,p_amount numeric,p_type text,p_category text,p_transaction_date date)returns cashflow.transaction language plpgsql security definer set search_path=cashflow,public,pg_temp as $$declare v_tenant uuid;v_owner uuid;v_result cashflow.transaction;begin select tenant_id,owner_id into v_tenant,v_owner from cashflow.bank_account where id=p_account_id;if v_tenant is null or not cashflow.denarius_can_operate(v_tenant)then raise exception'FORBIDDEN';end if;if p_amount<=0 or p_type not in('IN','OUT')then raise exception'INVALID_TRANSACTION';end if;insert into cashflow.transaction(account_id,owner_id,amount,type,category,transaction_date)values(p_account_id,v_owner,p_amount,p_type,nullif(trim(p_category),''),coalesce(p_transaction_date,current_date))returning*into v_result;return v_result;end$$;
create or replace function cashflow.denarius_create_invoice(p_tenant_id uuid,p_type text,p_total_amount numeric,p_currency text,p_issue_date date,p_due_date date,p_contact_name text)returns cashflow.invoice language plpgsql security definer set search_path=cashflow,public,pg_temp as $$declare v_owner uuid;v_result cashflow.invoice;begin select owner_id into v_owner from cashflow.tenant where id=p_tenant_id;if v_owner is null or not cashflow.denarius_can_operate(p_tenant_id)then raise exception'FORBIDDEN';end if;if p_type not in('AR','AP')or p_total_amount<=0 or p_due_date<p_issue_date then raise exception'INVALID_INVOICE';end if;insert into cashflow.invoice(tenant_id,owner_id,type,status,total_amount,currency,contact_name,issue_date,due_date,source_system)values(p_tenant_id,v_owner,p_type,'PENDING',p_total_amount,coalesce(nullif(p_currency,''),'CLP'),nullif(trim(p_contact_name),''),p_issue_date,p_due_date,'MANUAL')returning*into v_result;return v_result;end$$;
create or replace function cashflow.denarius_update_invoice(p_invoice_id uuid,p_status text,p_due_date date)returns void language plpgsql security definer set search_path=cashflow,public,pg_temp as $$declare v_tenant uuid;begin select tenant_id into v_tenant from cashflow.invoice where id=p_invoice_id;if v_tenant is null or not cashflow.denarius_can_operate(v_tenant)then raise exception'FORBIDDEN';end if;if p_status is not null and p_status not in('PAID','CANCELLED')then raise exception'INVALID_STATUS';end if;update cashflow.invoice set status=coalesce(p_status,status),due_date=coalesce(p_due_date,due_date)where id=p_invoice_id;end$$;
create or replace function cashflow.denarius_create_recurring(p_tenant_id uuid,p_type text,p_name text,p_amount numeric,p_frequency text,p_next_date date)returns cashflow.recurring_transaction language plpgsql security definer set search_path=cashflow,public,pg_temp as $$declare v_owner uuid;v_result cashflow.recurring_transaction;begin select owner_id into v_owner from cashflow.tenant where id=p_tenant_id;if v_owner is null or not cashflow.denarius_has_permission(p_tenant_id,'financial.write')then raise exception'FORBIDDEN';end if;if p_type not in('IN','OUT')or p_amount<=0 or p_frequency not in('WEEKLY','MONTHLY','QUARTERLY','YEARLY')or char_length(trim(p_name))<2 then raise exception'INVALID_RECURRING';end if;insert into cashflow.recurring_transaction(tenant_id,owner_id,name,type,amount,currency,frequency,next_date)values(p_tenant_id,v_owner,trim(p_name),p_type,p_amount,'CLP',p_frequency,p_next_date)returning*into v_result;return v_result;end$$;
revoke all on function cashflow.denarius_can_operate(uuid),cashflow.denarius_create_transaction(uuid,numeric,text,text,date),cashflow.denarius_create_invoice(uuid,text,numeric,text,date,date,text),cashflow.denarius_update_invoice(uuid,text,date),cashflow.denarius_create_recurring(uuid,text,text,numeric,text,date)from public,anon;grant execute on function cashflow.denarius_can_operate(uuid),cashflow.denarius_create_transaction(uuid,numeric,text,text,date),cashflow.denarius_create_invoice(uuid,text,numeric,text,date,date,text),cashflow.denarius_update_invoice(uuid,text,date),cashflow.denarius_create_recurring(uuid,text,text,numeric,text,date)to authenticated;
